    "explanation": "直列につないだ 2 つの電解槽について、各電極が陽極か陰極かを図から決め、それぞれの反応を書き出す問題。正しいのは第2・3・4文の 3 つ。\n\nまず極を決める。電池の記号は長い線が正極、短い線が負極である。図では長い線が電極 Ⅰ 側にあるので、電極 Ⅰ が正極につながる陽極、電極 Ⅳ が負極につながる陰極である。電極 Ⅱ と Ⅲ は導線で結ばれており、電子は Ⅲ から Ⅱ へ流れるので、電極 Ⅱ が電解槽 A の陰極、電極 Ⅲ が電解槽 B の陽極になる（直列では「陽極—陰極—陽極—陰極」の順に並ぶ）。\n\n各電極の反応は次のとおり。\n・電極 Ⅰ（陽極、Pt、CuSO₄ 水溶液）：白金は溶けないので水が酸化され、2H₂O → O₂ ＋ 4H⁺ ＋ 4e⁻。酸素が発生し、H⁺ が生じて液は酸性になる。\n・電極 Ⅱ（陰極、Pt、CuSO₄ 水溶液）：Cu²⁺ ＋ 2e⁻ → Cu。銅が析出して質量が増える。\n・電極 Ⅲ（陽極、C、KI 水溶液）：I⁻ は水より酸化されやすいので、2I⁻ → I₂ ＋ 2e⁻。ヨウ素が生じ、I⁻ と I₃⁻ をつくって液が褐色になる。\n・電極 Ⅳ（陰極、Pt、KI 水溶液）：K⁺ は還元されず水が還元され、2H₂O ＋ 2e⁻ → H₂ ＋ 2OH⁻。水素が発生し、OH⁻ が生じて pH が上がる。\n\nこれをもとに各文を判定する。第1文：電極 Ⅱ の質量は増えるが、電極 Ⅰ は白金の陽極で溶け出さないので質量は減らない（減るのは銅電極を陽極にしたとき）。誤り。第2文：Ⅱ は陰極（還元）、Ⅲ は陽極（酸化）。正しい。第3文：Ⅲ で生じた I₂ により褐色になる。正しい。第4文：Ⅳ で OH⁻ が生じ pH が増加する。正しい。第5文：A では酸素、B では水素で、同じ気体ではない。誤り。\n\n「白金・炭素などの不活性電極では、陽極で酸化されるのは Cl⁻・I⁻ などのハロゲン化物イオン、それが無ければ水（OH⁻）。陰極で還元されるのはイオン化傾向の小さい金属イオン（Cu²⁺・Ag⁺）、それが無ければ水（H⁺）」という優先順位を覚えておけば、どの組合せの電気分解でも同じ手順で解ける。",
