    "explanation": "ルシャトリエの原理（平衡移動の原理）を、圧力・触媒・温度・貴ガスの添加の 4 つの操作について確かめる問題。正解は⑤（オ）。\n\n平衡は「加えられた変化を打ち消す向き」に移動する。\n・圧力を高くする → 気体の分子数が減る向きへ移動する。①は左辺 2 分子・右辺 2 分子で分子数が変わらないので、圧力を変えても平衡は移動しない。\n・触媒 → 正反応・逆反応の活性化エネルギーを同じだけ下げ、平衡に達するまでの時間を短くするだけで、平衡の位置（平衡定数）は変えない。\n・加熱 → 吸熱反応（ΔH ＞ 0）の向きへ移動する。②は ΔH ＝ －92 kJ の発熱反応なので、加熱すると左（吸熱の向き）へ移動する。\n・体積一定で反応に関係しない気体（アルゴン）を加える → 全圧は上がるが、各成分の分圧（濃度）は変わらないので平衡は移動しない（圧力一定で加えると体積が増えて分圧が下がり、分子数が増える向きへ移動する。この違いが頻出）。\n・冷却 → 発熱反応（ΔH ＜ 0）の向きへ移動する。③は ΔH ＝ －57 kJ の発熱反応なので、冷却すると右（N₂O₄ が生じる向き）へ移動し、赤褐色の NO₂ が減って色が薄くなる。\n\n「圧力は分子数、温度は ΔH の符号、触媒と体積一定の貴ガスは動かさない」の 3 点で処理する。",
