    "explanation": "ルシャトリエの原理と触媒の役割。アは誤、イは正で、正解は③。\n\nア：誤り。酸化バナジウム(V) V₂O₅ は接触法（硫酸の製造）で使われるこの反応の触媒。触媒は活性化エネルギーを下げて正反応と逆反応の速度を同じ割合で速め、平衡に達するまでの時間を短くするが、平衡の位置（平衡定数）は変えない。すでに平衡状態にある混合気体に加えても SO₃ の物質量は増えない。\nイ：正しい。温度一定で容積を大きくすると全圧が下がる。圧力の減少を打ち消す向き、つまり気体の分子数が増える向き（左辺 3 分子 ＞ 右辺 2 分子なので左向き）に平衡が移動し、SO₃ は減少する。\n\n「触媒は速さを変えるが平衡は動かさない」「圧力を下げると分子数が増える向きへ動く」の 2 点。",
