    "question": "2018 年 11 月 16 日に第 26 回国際度量衡総会（CGPM）において、SI 基本単位（国際単位系において、基本単位として位置付けられている 7 つの SI 単位）の定義を改訂することが決議・承認され、2019 年 5 月 20 日から改訂された新定義が施行されている。この改訂には、物質量の単位である mol に関する定義の改訂も含まれており、新定義では 1 mol が次のように定義される。\n\n「1 mol は厳密に 6.02214076 × 10²³ の要素粒子または要素粒子の集合体（組成が明確にされたものに限る）で構成された系の物質量である。この数値は、アボガドロ定数 N_A を単位 mol⁻¹ で表したときの数値である。」\n\n定義の改訂によって、次の記述（ア〜ウ）で表される物質量の値が、改訂前と改訂後で厳密には一致しなくなったものがある。一致しなくなった記述の組合せとして最も適当なものを一つ選べ。\n\nア 1 mol の CH₄ に含まれる H 原子の物質量\nイ 1 × 10²³ 個の C 原子を含む CH₄ の物質量\nウ 1 g の ¹²C に含まれる C 原子の物質量",
    "choices": [
      "ア",
      "イ",
      "ウ",
      "アとイ",
      "イとウ",
      "アとウ",
      "アとイとウ"
    ],
    "answer": 4,
    "explanation": "mol の定義の改訂。旧定義は「12 g の ¹²C に含まれる原子の数」を 1 mol とし、アボガドロ定数は測定で決まる値（不確かさをもつ）だった。新定義は逆に、アボガドロ定数を厳密な定義値 6.02214076×10²³ /mol にしたので、「12 g の ¹²C」がちょうど 1 mol である保証はなくなった。厳密に一致しなくなるのはイとウで、正解は⑤。\n\nア：一致する。CH₄ 1 分子に H は 4 個なので、1 mol の CH₄ に H は 4 mol。分子中の原子の比だけで決まり、定義によらない。\nイ：一致しない。物質量＝粒子数 ÷ N_A。N_A の値が「測定値（不確かさつき）」から「厳密な定義値」に変わったので、1×10²³ 個に対応する物質量の値は厳密には同じにならない。\nウ：一致しない。旧定義では 12 g の ¹²C が厳密に 1 mol なので 1 g は厳密に 1/12 mol。新定義では ¹²C のモル質量は測定で決まる量（厳密に 12 g/mol ではない）になり、1 g の物質量も厳密には 1/12 mol ではない。\n\n改訂の要点は「¹²C 12 g を基準にする」から「粒子数を基準にする」への変更。粒子数や質量から求める物質量は影響を受け、比だけで決まる量は受けない。",
    "choiceNotes": [
      "誤り。1 mol の CH₄ 中の H は原子数の比で 4 mol と決まり、定義の改訂と無関係。",
      "誤り。イだけでなくウ（1 g の ¹²C）も厳密には 1/12 mol でなくなる。",
      "誤り。ウだけでなくイ（粒子数 ÷ N_A）も N_A の値の扱いが変わったので一致しない。",
      "誤り。アは分子中の原子数の比で決まるので一致する。",
      "正解。イは N_A が測定値から定義値に変わったため、ウは 12 g の ¹²C が厳密に 1 mol でなくなったため、値が厳密には一致しない。",
      "誤り。アは一致する。一致しないのはイとウ。",
      "誤り。アは原子数の比で決まる量で、改訂の影響を受けない。"
    ]
