    "explanation": "周期表を 3 つの区分に分け、それぞれに含まれる元素を具体的に思い浮かべて判断する問題。図から、A は 1・2 族（Li・Be・Na・Mg・K・Ca）、B は第4周期の 3〜12 族（Sc〜Zn の遷移元素と Zn）、C は 13〜18 族（B〜Ne、Al〜Ar、Ga〜Kr）である。正解は⑤（オ）。\n\n①：A の中で炎色反応を示すのは Li（赤）・Na（黄）・K（赤紫）・Ca（橙赤）で、イオン化エネルギーは同族では原子番号が大きいほど小さいので、A の中で最小は K である（Li はアルカリ金属の中では最大）。\n②：B は遷移元素で、原子番号が増えても電子は内側の M 殻（3d）に入るため、最外殻電子は 1 個または 2 個のまま変わらない。「原子番号とともに最外殻電子が増える」のは典型元素の性質である。\n③：B に含まれる Zn（12 族）は両性金属で、Zn ＋ 2HCl → ZnCl₂ ＋ H₂、Zn ＋ 2NaOH ＋ 2H₂O → Na₂[Zn(OH)₄] ＋ H₂ のように塩酸にも NaOH 水溶液にも溶ける。したがって「含まれない」は誤り。\n④：C には O（16 族・第2周期）が含まれる。地殻中の元素の存在量は O ＞ Si ＞ Al ＞ Fe の順で、最多は O である。\n⑤：C の Al（13 族・第3周期）は濃硝酸に入れると表面に緻密な酸化被膜（不動態）ができて内部が溶けない。不動態をつくる金属は Al・Fe・Ni（・Cr・Co）で、このうち C に入るのは Al。正しい。\n\n「両性金属は Al・Zn・Sn・Pb」「不動態は Al・Fe・Ni」「地殻は O・Si・Al・Fe の順」の 3 つの暗記事項を、周期表の位置と結びつけて確認しておく。",
