    "question": "濃硫酸の工業的製法について述べた次の文中の A〜D の語句について、正しいものの組合せを一つ選べ。\n\n濃硫酸は工業的には接触法でつくられる。まず、硫黄を燃焼させて X を生成させる。次に、酸化バナジウム(V) を触媒に用いて X を酸化して【A：二酸化硫黄】とする。さらに A を【B：濃硫酸】に吸収させて【C：発煙硫酸】とし、これを【D：水】に吸収させて濃硫酸とする。",
