    "explanation": "炎色反応から元素を決め、イオンの電子数を比べる問題。赤紫の炎色反応はカリウム K（原子番号 19）。K⁺ は電子を 1 個失って電子数 18（Ar と同じ配置）。電子数 18 のものを 2 つ含む組み合わせはオ（Cl⁻ と Ca²⁺）。\n\nア：F⁻（10）と Mg²⁺（10）。互いには等しいが K⁺ とは違う。\nイ：O²⁻（10）と Al³⁺（10）。同上。\nウ：S²⁻（18）は合うが、Na⁺（10）が違う。\nエ：Br⁻（36）と Ne（10）。どちらも違う。\nオ：Cl⁻（17＋1＝18）と Ca²⁺（20−2＝18）。両方 K⁺ と同じ。\n\n炎色反応は「Li 赤・Na 黄・K 赤紫・Cu 青緑・Ca 橙赤・Sr 紅・Ba 黄緑」。電子数は「原子番号 − イオンの価数」で数える。",
    "choiceNotes": [
      "誤り。F⁻ と Mg²⁺ は電子数 10 で、K⁺（18）とは違う。",
      "誤り。O²⁻ と Al³⁺ は電子数 10。",
      "誤り。S²⁻ は 18 だが Na⁺ は 10。",
      "誤り。Br⁻ は 36、Ne は 10。",
      "正解。A はカリウムで K⁺ の電子数は 18。Cl⁻（18）と Ca²⁺（18）はどちらも同じ。"
    ],
