    "answer": 4,
    "explanation": "アンモニアが関わる反応の正誤。正しいのは C と D で、正解はオ。\n\nA：誤り。Fe³⁺ にアンモニア水を加えると赤褐色の Fe(OH)₃ が沈殿する。緑白色の沈殿は Fe²⁺ の Fe(OH)₂。\nB：誤り。アンモニアソーダ法で NaCl 飽和水溶液にアンモニアと CO₂ を通して得られるのは炭酸水素ナトリウム NaHCO₃ の沈殿。これを加熱して初めて炭酸ナトリウムになる。\nC：正しい。オストワルト法の第一段階で、白金触媒によりアンモニアが一酸化窒素 NO に酸化される（4NH₃ ＋ 5O₂ → 4NO ＋ 6H₂O）。\nD：正しい。Cu²⁺ に過剰のアンモニア水を加えると、Cu(OH)₂ の沈殿が溶けて深青色の [Cu(NH₃)₄]²⁺ になる。\n\n「Fe²⁺ は緑白、Fe³⁺ は赤褐」「ソーダ法で沈殿するのは NaHCO₃」が定番の引っかけ。",
