    "answer": 4,
    "explanation": "硫黄の化合物の性質の穴埋め。誤りはオで、これが正解。\n\nア：正しい。FeS ＋ 2HCl → FeCl₂ ＋ H₂S（希硫酸でもよい。弱酸の塩に強酸を加える製法）。\nイ：正しい。SO₂ は水に溶けて亜硫酸 H₂SO₃ となり弱酸性を示す。\nウ：正しい。式では S の酸化数が ＋4 → ＋6 に増え、電子を放出しているので還元剤。SO₂ は H₂S に対しては酸化剤にもなる。\nエ：正しい。濃硫酸は沸点が高く不揮発性なので、揮発性の酸の塩から HCl を追い出せる。NaCl ＋ H₂SO₄ → NaHSO₄ ＋ HCl。\nオ：誤り。スクロースが黒化するのは濃硫酸の脱水作用（C₁₂H₂₂O₁₁ → 12C ＋ 11H₂O）。酸化作用は熱濃硫酸が Cu を溶かして SO₂ を出すときの性質。\n\n濃硫酸の性質「不揮発性・吸湿性・脱水作用・酸化作用（加熱時）」を反応例とセットで覚える。",
