    "explanation": "三元触媒は Pt・Pd・Rh を担持したもので、排気ガス中の CO と炭化水素を酸化し、NOₓ を還元して同時に無害化する。塩化パラジウム(II) PdCl₂ は、エチレンを酸素で酸化してアセトアルデヒドをつくるワッカー法（ヘキスト・ワッカー法）の触媒（塩化銅(II) CuCl₂ と併用）。正解は⑦のパラジウム Pd。\n\n2CH₂＝CH₂ ＋ O₂ → 2CH₃CHO（PdCl₂・CuCl₂ 触媒）。以前はアセチレンに水を付加する方法（HgSO₄ 触媒）でつくっていたが、水銀の毒性の問題からワッカー法に代わった。\n\nパラジウムは自分の体積の 900 倍以上の水素を吸収する性質（水素吸蔵）でも知られる。\n\n触媒と元素の対応：接触法 V₂O₅（バナジウム）、ハーバー・ボッシュ法 Fe₃O₄（鉄）、オストワルト法 Pt（白金）、ワッカー法 PdCl₂（パラジウム）。",
