    "explanation": "酸・塩基の強さの違いを利用した芳香族化合物の抽出分離。「塩になれば水層、遊離すればエーテル層」が原則で、さらに「いま水層にあるものをエーテルに移すにはエーテルを加える必要があり、エーテル層にあるものを水層に移すには水溶液を加えるだけでよい」という操作の形にも注意する。正解は①（ア）。\n\n最初に NaOH 水溶液を加えると、酸性の化合物であるフェノール（－OH）と安息香酸（－COOH）はナトリウム塩となって水層へ、中性のニトロベンゼン（－NO₂）と塩基性のアニリン（－NH₂）はエーテル層に残る。\n\n操作 a（水層 → 水層① ＋ エーテル層①・A）：水層のナトリウムフェノキシドと安息香酸ナトリウムのうち、片方だけをエーテルに戻す操作である。炭酸より弱い酸であるフェノールは CO₂ を吹きこむと遊離するが、炭酸より強い酸である安息香酸は遊離しない。水層からエーテルへ移すのでエーテルも必要。よって（は）。A ＝ フェノール。\n操作 b（水層① → 水層② ＋ エーテル層②・B）：残った安息香酸ナトリウムに塩酸を加えて安息香酸を遊離させ、エーテルに移す。よって（ろ）。B ＝ 安息香酸。\n操作 c（エーテル層 → 水層③ ＋ エーテル層③・C）：エーテル層のアニリンとニトロベンゼンのうち、塩酸を加えるとアニリンだけがアニリン塩酸塩となって水層へ移る。すでにエーテル層があるのでエーテルを加える必要はなく、（い）。C ＝ ニトロベンゼン。\n操作 d（水層③ → 水層④ ＋ エーテル層④・D）：アニリン塩酸塩に NaOH 水溶液を加えてアニリンを遊離させ、エーテルに移す。よって（に）。D ＝ アニリン。\n\n「酸の強さは 塩酸・硫酸 ＞ カルボン酸 ＞ 炭酸 ＞ フェノール」の順であることが、CO₂ でフェノールだけを遊離できる根拠になる。",
