    "question": "油脂とセッケンについて述べた次の文中の A〜D の語句について、正しいものの組合せを一つ選べ。\n\n油脂は、1 個のグリセリン分子に 3 個の高級脂肪酸が【A：エステル結合】した物質である。油脂に水酸化ナトリウム水溶液を加えて加熱すると、油脂は【B：脱重合】され、高級脂肪酸のナトリウム塩とグリセリンを生成する。生成された高級脂肪酸のナトリウム塩は、【C：界面活性剤】と呼ばれ、水と油をなじませる作用を有する。この水溶液に油を加えてよく混合すると、油滴は微粒子となって分散する。これを【D：凝析】という。",
