    "explanation": "油脂の構造とセッケンのはたらきの用語を問う問題。正しいのは A と C。\n\nA：正しい。油脂は 3 価アルコールのグリセリンと高級脂肪酸 3 分子のエステル（トリグリセリド）。\nB：誤り。油脂を NaOH で加水分解する操作はけん化。脱重合は高分子を単量体に戻す反応で無関係。\nC：正しい。脂肪酸ナトリウム（セッケン）は親水基と疎水基をもつ界面活性剤。\nD：誤り。油滴がセッケンのミセルに取り込まれて分散する現象は乳化。凝析は疎水コロイドが電解質で沈殿する現象。\n\n「けん化 → セッケン → 乳化」の一連の用語をセットで覚える。",
