    "explanation": "フェノールと芳香族化合物の反応の正誤。正しいのは B と D で、正解はイ。\n\nA：誤り。クメンヒドロペルオキシドを希硫酸で分解すると、フェノールとアセトン（アセトアルデヒドではない）が得られる。\nB：正しい。ヒドロキシ基がベンゼン環の反応性を高めるので、フェノールはベンゼンより置換反応（ニトロ化・臭素化など）が起こりやすい。臭素水を加えるだけで白色沈殿を生じる。\nC：誤り。OH 基はオルト・パラ配向性。混酸で加熱すると 2,4,6-トリニトロフェノール（ピクリン酸）が生じ、m-位には入らない。\nD：正しい。ベンゼン環に付いたアルキル基は KMnO₄ で酸化され、炭素数によらず COOH になる（安息香酸）。\nE：誤り。さらし粉水溶液で赤紫色になるのはアニリン。フェノールは塩化鉄(III) 水溶液で紫色。\n\n「クメン法の副産物はアセトン」「OH・NH₂ はオルト・パラ配向」「さらし粉はアニリン、FeCl₃ はフェノール」の 3 つは繰り返し出る。",
