    "explanation": "糖類を多糖・二糖・単糖に分類し、単糖はさらに炭素数で六炭糖と五炭糖に分ける、という分類の知識を炭素数の大小として問う問題。正解は①（ア）。\n\n② セルロースは多数のグルコース（β-グルコース）が縮合した多糖 (C₆H₁₀O₅)ₙ で、1 分子中の炭素数は 6n と桁違いに多い。\n① マルトース（麦芽糖）は 2 分子の α-グルコースが縮合した二糖 C₁₂H₂₂O₁₁ で、炭素数 12。\n③ ガラクトースと ⑤ フルクトースはどちらも単糖の六炭糖 C₆H₁₂O₆ で、炭素数 6。ガラクトースはグルコースの立体異性体（乳糖の成分）、フルクトースは果糖でケトン基をもつ。\n④ デオキシリボースは DNA を構成する五炭糖 C₅H₁₀O₄ で、炭素数 5。リボース C₅H₁₀O₅ の 2 位の炭素から酸素が 1 つ取れた（デオキシ）構造である。\n\nしたがって ② ＞ ① ＞ ③ ＝ ⑤ ＞ ④。「多糖 ≫ 二糖（12）＞ 六炭糖（6）＞ 五炭糖（5）」という枠組みで、各糖がどこに属するかを即答できるようにしておく。",
