    "question": "以下の高分子について、次の記述のうち正しいものはいくつあるか。その個数を一つ選べ。\n\n・乳酸から合成されるポリ乳酸は生分解性樹脂である。\n・ポリエチレンは導電性樹脂である。\n・光硬化性樹脂は、光をあてることにより重合が促進し硬化する。\n・シリコーンゴムは、不飽和結合をもたないため天然ゴムに比べて劣化しにくい。",
