    "question": "次の中に正しい記述はいくつあるか。その個数を一つ選べ。\n\n・①〜③の全てのアミノ酸に鏡像異性体が存在する。\n・①のアミノ酸は α-アミノ酸で 2 番目に分子量が小さい。\n・②のアミノ酸はタンパク質が三次構造を取る際のジスルフィド結合に関与する。\n・③のアミノ酸は塩基性アミノ酸である。\n・グルタチオンはビウレット反応を示す。",
