    "explanation": "セルロース（A）からつくる再生繊維・半合成繊維の穴埋めで、誤りを選ぶ。正解はオ。\n\nア：正しい。シュバイツァー試薬（[Cu(NH₃)₄](OH)₂ の水溶液）に溶かして希硫酸中に押し出したものが銅アンモニアレーヨン（キュプラ）。\nイ：正しい。NaOH と CS₂ で処理して NaOH 水溶液に溶かした赤褐色のコロイド溶液がビスコース。希硫酸中に押し出すとビスコースレーヨン。\nウ：正しい。ビスコースを薄い膜状に再生したものがセロハン。\nエ：正しい。セルロースは多数の –OH の水素結合で強く集まっており、酢酸エステルにして水素結合を弱めると成形しやすくなる。\nオ：誤り。無水酢酸でアセチル化し、一部を加水分解して繊維にしたものはアセテート（半合成繊維）。キュプラは銅アンモニアレーヨンの別名で、アと同じもの。\n\n「再生繊維（レーヨン・キュプラ）はセルロースのまま、半合成繊維（アセテート）はエステル化したもの」の区別が要点。",
