    "stem": "A〜F は次の中のいずれか 1 つの分子である。\n\nグリコーゲン　ラクトース　アミロース　スクラーゼ　スクロース\nアラニン　リノール酸　セルロース　トレハロース　アミラーゼ\n\nA〜F を含む水溶液が入っている試験管をそれぞれ試験管 A〜F とする。試験管 A〜F について以下の実験 1〜5 を行った。\n\n実験 1　試験管 A〜F にヨウ素ヨウ化カリウム水溶液を加えたところ、試験管 A は赤褐色を、試験管 C は濃青色を呈した。\n実験 2　試験管 A〜F に水酸化ナトリウム水溶液を加えてよく混ぜたのち、少量の硫酸銅(II)水溶液を加えたところ、D と E の各試験管は赤紫色を呈した。\n実験 3　試験管 B にフェーリング液を加えて加熱したところ赤色沈殿が生じたが、試験管 F に同様の操作を行っても赤色沈殿は生じなかった。\n実験 4　試験管 C に試験管 E の水溶液を少量加え、温和な条件で反応させたところ化合物 G が生じた。その後、G を含む試験管 C にフェーリング液を加えて加熱したところ赤色沈殿が生じた。\n実験 5　試験管 F に試験管 D の水溶液を少量加え、温和な条件で反応させた。その後、試験管 F にフェーリング液を加えて加熱したところ赤色沈殿が生じた。",
