    "question": "以下の文章中の A〜D の語句で正しいものはいくつあるか。その個数を一つ選べ。\n\n新たな置換基などにより特別な機能を備えるようになった高分子化合物を機能性高分子化合物という。一般的な高分子化合物は電気を導きにくいが、白川英樹らはアセチレンを付加重合したポリアセチレンに【 A：ホウ素 】を添加すると金属に近い電気伝導性を示す樹脂が得られることを発見した。このような樹脂を導電性樹脂という。また、溶液中のイオンを別のイオンと交換するはたらきをもつ合成樹脂をイオン交換樹脂という。図に示したイオン交換樹脂 X は、【 B：p-ジビニルベンゼン 】とスチレンを【 C：付加縮合 】させた多孔質の立体網目状の構造の樹脂に【 D：濃硫酸 】を作用させると得られる。この樹脂に電解質水溶液を通すと、樹脂の H⁺ と電解質の陽イオンが交換される。このような樹脂を陽イオン交換樹脂という。",
