    "explanation": "機能性高分子の穴埋め。正しいのは B と D の 2 つで、正解はウ。\n\nA：誤り。ポリアセチレンに添加して導電性を高めるのはヨウ素（I₂）。二重結合と単結合が交互に並ぶ鎖に少量のヨウ素を加えると電子が動きやすくなる。\nB：正しい。図で 2 本の鎖を橋かけしているベンゼン環は p-ジビニルベンゼン由来。これが立体網目状の構造をつくり、樹脂を水に溶けにくくする。\nC：誤り。スチレンと p-ジビニルベンゼンはどちらもビニル基をもち、付加重合（共重合）でつながる。付加縮合はフェノール樹脂や尿素樹脂のつくり方。\nD：正しい。濃硫酸でベンゼン環をスルホン化して –SO₃H を導入すると陽イオン交換樹脂になる。\n\n覚え方：「ポリアセチレン＋ヨウ素で導電」「スチレン＋p-ジビニルベンゼンは付加重合、スルホン化で陽イオン交換樹脂、–N⁺(CH₃)₃OH⁻ なら陰イオン交換樹脂」。",
