    "explanation": "タンパク質の基本構造。ア は誤、イ は正で、正解は③。\n\nア：誤り。タンパク質はアミノ酸の配列順序（一次構造）だけでなく、どのアミノ酸をいくつ含むか（組成）もタンパク質ごとに違う。すべてのタンパク質が 20 種類を 5％ずつ含むはずはなく、例えば絹のフィブロインはグリシンとアラニンが大部分を占める。「20 種類」という正しい数字に「同じ割合」を紛れ込ませた引っかけ。\nイ：正しい。タンパク質は多数の α-アミノ酸が、一方のカルボキシ基と他方のアミノ基から水がとれて –CO–NH–（ペプチド結合＝アミド結合の一種）でつながったポリペプチド。ペプチド結合のないタンパク質はない。\n\nビウレット反応（2 個以上のペプチド結合で赤紫）が「タンパク質に必ずペプチド結合がある」ことの検出法。",
