    "explanation": "セルロースの加水分解と用途。アは誤、イは正で、正解は③。\n\nア：誤り。セルロースは β-グルコースが縮合重合した多糖で、希硫酸中で長時間煮沸すると完全に加水分解されてグルコースになる。しかしグルコースは水溶液中で α-グルコース・鎖状構造・β-グルコースが互いに変化し合う平衡状態にあるので、もとが β-グルコースの重合体でも、溶液中には α-グルコースも含まれる（平衡では α 型が約 1/3、β 型が約 2/3）。「β からできているから β しかない」と思わせる引っかけ。\nイ：正しい。綿（コットン）や麻はほぼ純粋なセルロースからなる植物繊維。木材のパルプもセルロースが主成分で、紙やレーヨン（再生繊維）の原料になる。\n\nセルロースの加水分解：希酸で煮沸→グルコース、セルラーゼ→セロビオース→グルコース。水溶液中のグルコースは α・鎖状・β の平衡混合物で、この鎖状構造が還元性のもと。",
